def is_between_3s(row, col):
    """Check if position (row, col) is between 3s in the same row"""
    has_left_3 = False
    has_right_3 = False

    # Check left
    for c in range(col-1, -1, -1):
        if row[c] == 3:
            has_left_3 = True
            break
        if row[c] != 6:
            break

    # Check right
    for c in range(col+1, len(row)):
        if row[c] == 3:
            has_right_3 = True
            break
        if row[c] != 6:
            break

    return has_left_3 and has_right_3

